q=py('import pathlib,json,os;O=pathlib.Path('+repr(str(O))+');r={};\nfor n in ["guest-exit.json","guest-controller-terminal.json","guest-supervisor.json"]:\n p=O/n\n if p.exists():\n  v=json.loads(p.read_text());r[n]={k:v[k] for k in v if k!="owned"}\nr["stdoutTail"]=(O/"guest.stdout").read_text(errors="replace")[-1100:];r["stderrTail"]=(O/"guest.stderr").read_text(errors="replace")[-500:];print(json.dumps(r))');save('cleanup-remote-observation.json',q);print(q['stdout'])
